type Props = {
  size?: number;
  className?: string;
  color?: string;
} & React.SVGProps<SVGSVGElement>;

export function SmilingAgentHeadphonesIcon({
  size = 16,
  className = "",
  color = "#ffffff",
  ...props
}: Props) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      {...props}
    >
      {/* Head (circle) */}
      <circle
        cx="12"
        cy="10"
        r="4"
        stroke={color}
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
        fill="none"
      />

      {/* Smile */}
      <path
        d="M9.5 12.8c0.7 0.8 1.9 1.3 3 1.3s2.3-0.5 3-1.3"
        stroke={color}
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
        fill="none"
      />

      {/* Eyes (filled for a friendly look) */}
      <circle cx="10.5" cy="9.4" r="0.45" fill={color} />
      <circle cx="13.5" cy="9.4" r="0.45" fill={color} />

      {/* Headphones band (over the head) */}
      <path
        d="M4 12c0-3.7 3.6-6.6 8-6.6s8 2.9 8 6.6"
        stroke={color}
        strokeWidth="1.6"
        strokeLinecap="round"
        strokeLinejoin="round"
        fill="none"
      />

      {/* Left ear pad */}
      <rect
        x="2.6"
        y="12.2"
        width="3.2"
        height="4.6"
        rx="0.9"
        stroke={color}
        strokeWidth="1.2"
        fill={color}
      />

      {/* Right ear pad */}
      <rect
        x="18.2"
        y="12.2"
        width="3.2"
        height="4.6"
        rx="0.9"
        stroke={color}
        strokeWidth="1.2"
        fill={color}
      />

      {/* Optional small collar/shoulders so it reads as "colleague" */}
      <path
        d="M8.5 16.8c.9.9 2.4 1.6 3.5 1.6s2.6-.7 3.5-1.6"
        stroke={color}
        strokeWidth="1.2"
        strokeLinecap="round"
        strokeLinejoin="round"
        fill="none"
      />
    </svg>
  );
}
